import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]

    return 0.1 * (x1**2 + x2**2) + 0.05 * x1 * x2 + 0.1 * (x1**3 + x2**3) * np.exp(-0.1 * (x1**2 + x2**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.1 * (x1**2 + x2**2) + 0.5 * np.sin(3 * x1) * np.exp(-0.2 * (x1**2 + x2**2)) + 0.05 * x1 * x2 + 0.2 * x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.1 * (x1**2 + x2**2) + 0.5 * np.sin(3 * x1) * np.exp(-0.2 * (x1**2 + x2**2)) + 0.05 * x1 * x2 + 0.2 * x1 + 0.1 * np.tanh(x1 + x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]

    return 0.1 * (x1**2 + x2**2) + 0.05 * x1 * x2 + 0.1 * (x1**3 + x2**3) * np.exp(-0.1 * (x1**2 + x2**2)) + 0.05 * np.sinh(np.sin(3 * x1) + np.cos(3 * x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.1 * (x1**2 + x2**2) + 0.5 * np.sin(3 * x1) * np.exp(-0.2 * (x1**2 + x2**2)) + 0.05 * x1 * x2 + 0.2 * x1 + 0.1 * np.cosh(x1 - x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.2 * (x1**2 + 0.5*x2**2 + 0.1*x1*x2) + np.exp(-0.3 * (x1**2 + x2**2)) * (0.1 * x1 + 0.1 * x2) + 0.05 * x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]

    return 0.1 * (x1**2 + x2**2)**0.75 + 0.05 * x1 * x2 + 0.05 * np.exp(-0.1 * (x1**2 + x2**2)) * np.cos(2 * np.pi * x1) + 0.1 * np.exp(x1 - x2) / (1 + np.exp(x1 - x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.15 * (x1**2 + x2**2) + 0.3 * np.cos(2 * x1) * np.exp(-0.15 * (x1**2 + x2**2)) * np.tanh(x1 + x2) + 0.05 * (np.exp(-x1)/(1 + np.exp(-x1))) * x1 + 0.1 * (np.exp(-x2)/(1 + np.exp(-x2))) * x2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.1 * (x1**2 + x2**2) + 0.5 * np.sin(3 * x1) * np.exp(-0.2 * (x1**2 + x2**2)) + 0.05 * x1 * x2 + 0.2 * x1 + 0.1 * np.tanh(x1 + x2) + 0.1 / (1 + np.exp(x1 - x2)))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.3*x1**2 - 0.2*x2**2 + 0.1*x1*x2 + 0.4*np.cos(2*x1) * np.cos(x2) + 0.1*np.arctan(x1+x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.1 * (x1**2 + x2**2) + 0.1 * np.exp(-0.2 * (x1**2 + x2**2)) + 0.05 * np.sinh(np.sin(3 * x1) + np.cos(3 * x2)) + 0.05 * np.arctan(np.sin(x1) * np.cos(x2) * np.exp(-0.1 * (x1**2 + x2**2)))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]

    return 0.1 * (x1**2 + x2**2) + 0.05 * x1 * x2 * np.cos(x1 + x2)

