import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]

    return 0.1 * (x1**2 + x2**2) + 0.05 * x1 * x2 + 0.1 * (x1**3 + x2**3) * np.exp(-0.1 * (x1**2 + x2**2)) + 0.05 * np.sinh(np.sin(3 * x1) + np.cos(3 * x2)) + 0.01 * np.log(1 + np.sin(5 * np.sqrt(x1**2 + x2**2)))
